INSERT INTO cms_block(id,block_key,title,body,items_json,position,visible,version) VALUES ('0e6c2c51-c0ed-4126-941f-11e19f19d14a','benefits','Ձեր աշխատանքի համար՝ մեկ հարթակ','Գաղափարները կազմակերպելու և պահպանելու պարզ միջոց։','[{"title": "Անձնական տարածք", "body": "Ձեր փաստաթղթերը հասանելի են միայն ձեր հաշվով։"}, {"title": "Հայերեն միջավայր", "body": "Աշխատեք հարմար և հասկանալի միջավայրում։"}, {"title": "Պահպանված աշխատանք", "body": "Վերադարձեք ձեր սևագրերին և շարունակեք խմբագրումը։"}]',0,TRUE,0);
INSERT INTO cms_block(id,block_key,title,body,items_json,position,visible,version) VALUES ('855f4365-5c1c-48cf-863a-8a0dbf1be3e9','tools','Տարածք յուրաքանչյուր գաղափարի համար','Այս պահին հասանելի է ձեռքով խմբագրումը։ AI գործիքները մշակման փուլում են։','[{"title": "Կուրսային աշխատանք", "body": "Ստեղծեք, խմբագրեք և պահպանեք ձեր աշխատանքը։"}, {"title": "Դիպլոմային աշխատանք", "body": "Ստեղծեք, խմբագրեք և պահպանեք ձեր աշխատանքը։"}, {"title": "Ռեֆերատ", "body": "Ստեղծեք, խմբագրեք և պահպանեք ձեր աշխատանքը։"}, {"title": "Զեկույց", "body": "Ստեղծեք, խմբագրեք և պահպանեք ձեր աշխատանքը։"}]',10,TRUE,0);
INSERT INTO cms_block(id,block_key,title,body,items_json,position,visible,version) VALUES ('0f70f3b9-5c16-48e4-9f82-7b3c3c712e45','how','Կենտրոնացեք ձեր գաղափարի վրա։','Ձեր աշխատանքը պահպանվում է ձեր հաշվում։','[{"title": "Ստեղծեք հաշիվ", "body": "Գրանցվեք և բացեք ձեր անձնական տարածքը։"}, {"title": "Սկսեք փաստաթուղթ", "body": "Ընտրեք աշխատանքի տեսակը և ավելացրեք բովանդակությունը։"}, {"title": "Խմբագրեք և պահպանեք", "body": "Վերադարձեք ձեր աշխատանքին ցանկացած պահի։"}]',20,TRUE,0);
INSERT INTO cms_block(id,block_key,title,body,items_json,position,visible,version) VALUES ('ff54ae1a-cd00-4a8f-87fe-33afb0dbda75','examples','Ձեր աշխատանքը՝ ձեր վերահսկողությամբ','Պահպանեք սևագիր, վերանվանեք այն և շարունակեք խմբագրումը։','[]',30,TRUE,0);
INSERT INTO cms_block(id,block_key,title,body,items_json,position,visible,version) VALUES ('70a1ea23-ac9f-4bb9-b32d-2f166ffecc18','pricing','Coins։ Առանց բաժանորդագրության։','Հետագայում Coins-ը կօգտագործվի AI գործիքների համար։ Այժմ սևագրերի ստեղծումն ու խմբագրումն անվճար են։ Գնումները դեռ հասանելի չեն։','[]',40,TRUE,0);
INSERT INTO cms_block(id,block_key,title,body,items_json,position,visible,version) VALUES ('5c4b42f3-6aea-4801-9b02-0b8a413cd457','faq','Հաճախ տրվող հարցեր','','[{"title": "Ի՞նչ կարող եմ անել հիմա։", "body": "Ստեղծել հաշիվ և խմբագրել անձնական փաստաթղթեր։"}, {"title": "AI գեներացիան հասանելի՞ է։", "body": "Դեռ ոչ։ Այն մշակման փուլում է։"}, {"title": "Կա՞ ամսական բաժանորդագրություն։", "body": "Ոչ։ Նախատեսված է Coins-ի միանվագ գնում։ Վճարումներ դեռ չեն ընդունվում։"}]',50,TRUE,0);
INSERT INTO cms_block(id,block_key,title,body,items_json,position,visible,version) VALUES ('4b91755d-ddf7-418c-8f06-132e09948c26','cta','Ձեր հաջորդ գաղափարին՝ նոր սկիզբ։','Ստեղծեք ձեր առաջին փաստաթուղթը։','[]',60,TRUE,0);
