INSERT INTO cmscontent(id,content_key,content_value) SELECT '9e7e4ff4-7b2b-4bb2-bb29-590ad4c4bb78','seoDescription','Ակադեմիական փաստաթղթերի ստեղծման և խմբագրման անձնական տարածք։' WHERE NOT EXISTS (SELECT 1 FROM cmscontent WHERE content_key='seoDescription');
INSERT INTO cmscontent(id,content_key,content_value) SELECT '98e94ca3-1071-4d24-8119-51fb2642be2d','contact','Կոնտակտային տվյալները դեռ չեն հրապարակվել։' WHERE NOT EXISTS (SELECT 1 FROM cmscontent WHERE content_key='contact');
INSERT INTO cmscontent(id,content_key,content_value) SELECT 'e43819e0-9eac-4a88-b865-147ba94588ff','privacy','Այս մշակվող տարբերակը պահպանում է հաշվի տվյալները և ձեր փաստաթղթերը։ Գործարկումից առաջ այստեղ պետք է հրապարակվի ծառայության ամբողջական գաղտնիության քաղաքականությունը։' WHERE NOT EXISTS (SELECT 1 FROM cmscontent WHERE content_key='privacy');
INSERT INTO cmscontent(id,content_key,content_value) SELECT 'f37b0cbe-3080-4607-9a7e-0245f60cbfaf','terms','Հարթակը մշակման փուլում է։ AI և վճարային ծառայությունները դեռ հասանելի չեն։ Գործարկումից առաջ այստեղ պետք է հրապարակվեն ծառայության ամբողջական պայմանները։' WHERE NOT EXISTS (SELECT 1 FROM cmscontent WHERE content_key='terms');
